import 'dart:io';import 'package:dio/dio.dart';import 'package:flutter/foundation.dart';abstract class Failure {  final String errMessage;  const Failure(this.errMessage);}class ServerFailure extends Failure {  ServerFailure(super.errMessage);  factory ServerFailure.unauthorized() {    return ServerFailure("Unauthorized access. Please login again.");  }  factory ServerFailure.fromDioError(DioException dioError) {    return ServerFailure(ApiErrorHandler.handleError(dioError).message);  }  factory ServerFailure.fromResponse(int? statusCode, dynamic response) {    return ServerFailure(ApiErrorHandler.handleBadResponse(statusCode, response).message);  }}class ApiErrorHandler {  static ApiErrorModel handleError(dynamic error) {    if (error is DioException) {      switch (error.type) {        case DioExceptionType.connectionTimeout:          return ApiErrorModel(message: "⏳ Connection timeout, please try again.");        case DioExceptionType.sendTimeout:          return ApiErrorModel(message: "🚀 Request send timeout, please try again.");        case DioExceptionType.receiveTimeout:          return ApiErrorModel(message: "⏳ Response receive timeout, please try again.");        case DioExceptionType.badResponse:          return handleBadResponse(error.response?.statusCode, error.response?.data);        case DioExceptionType.cancel:          return ApiErrorModel(message: "❌ Request was cancelled.");        case DioExceptionType.connectionError:          return ApiErrorModel(message: "📶 No internet connection, please check your network.");        case DioExceptionType.badCertificate:          return ApiErrorModel(message: "⚠️ SSL Certificate error! The server's certificate is invalid or untrusted.");        case DioExceptionType.unknown:          return ApiErrorModel(message: "⚠️ Unexpected error occurred, please try again.");      }    } else if (error is SocketException) {      return ApiErrorModel(message: "📶 No internet connection.");    } else {      return ApiErrorModel(message: "⚠️ Unexpected error: ${error.toString()}");    }  }  static ApiErrorModel handleBadResponse(int? statusCode, dynamic response) {    String message = "⚠️ An unexpected error occurred.";    Map<String, dynamic>? details;    if (response is Map<String, dynamic>) {      if (response.containsKey('message')) {        message = response['message'];      } else if (response.containsKey('error')) {        message = response['error'];      }      if (response.containsKey('errors') && response['errors'] is List) {        details = {          "errors": List<String>.from(response['errors'].map((e) => e.toString()))        };      }    } else if (response is String) {      message = response;    }    if (statusCode != null) {      switch (statusCode) {        case 400:          message = message.isNotEmpty ? message : "❌ Bad request, please check your input.";          break;        case 401:          message = message.isNotEmpty ? message : "🔐 Unauthorized, please check your credentials.";          break;        case 403:          message = message.isNotEmpty ? message : "⛔ Forbidden, you don't have permission.";          break;        case 404:          message = message.isNotEmpty ? message : "🔍 Resource not found.";          break;        case 422:          message = message.isNotEmpty ? message : "⚠️ Validation error, please check your inputs.";          break;        case 500:          message = message.isNotEmpty ? message : "🔥 Internal server error, try again later.";          break;        case 502:          message = message.isNotEmpty ? message : "🚧 Bad gateway, try again later.";          break;        case 503:          message = message.isNotEmpty ? message : "🚧 Service unavailable, please try later.";          break;        default:          message = message.isNotEmpty ? message : "⚠️ Unexpected error occurred. Status code: $statusCode";      }    }    if (kDebugMode) {      debugPrint("❌ API Error: $message");      if (details != null) debugPrint("🔍 Details: ${details.toString()}");    }    return ApiErrorModel(message: message, details: details);  }}class ApiErrorModel {  final String message;  final Map<String, dynamic>? details;  ApiErrorModel({required this.message, this.details});  @override  String toString() {    return "ApiErrorModel(message: $message, details: $details)";  }}